/*
Theme Name: Careful Shopper — Twenty Twenty-Five Child
Template: twentytwentyfive
Author: Careful Shopper demo
Description: Editorial styling for the Careful Shopper bike-security guide.
Version: 1.2.0
Text Domain: careful-shopper
*/
:root{--green:#006633;--ink:#0F1111;--blue:#0033FF;--brown:#663300;--yellow:#FDF6D8;--gold:#CC9900;--beige:#F6F2EA;--mint:#EAF3EE;--line:#DDDDDD}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:#FFFFFF;color:var(--ink);font-family:Verdana,Geneva,Arial,sans-serif;font-size:1rem;line-height:1.6}
body,button,a,table{font-family:Verdana,Geneva,Arial,sans-serif}
a{color:var(--blue);font-weight:700;text-decoration:underline;text-underline-offset:.12em}
a:hover{color:#0033FF}
a:focus-visible,button:focus-visible{outline:.1875rem solid var(--gold);outline-offset:.1875rem}
.site-header{padding:1rem;border-bottom:.125rem solid var(--line);background:#FFFFFF}
.header-inner{width:min(60rem,100%);margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:1.5rem;min-width:0}
.brand{display:flex;align-items:center;gap:.75rem;min-width:0;color:var(--green);text-decoration:none;flex:0 0 auto}
.brand-mark{width:3rem;height:3rem;display:grid;place-items:center;flex:0 0 3rem;border:.0625rem solid var(--green);border-radius:.75rem;background:var(--mint);font-size:1.4rem;font-weight:700;color:var(--green)}
.brand-copy{display:flex;flex-direction:column;line-height:1.2}
.brand-name{font-size:1.4rem;font-weight:700;color:var(--green);white-space:nowrap}
.tagline{font-size:1rem;font-weight:400;color:var(--ink);white-space:nowrap}
.desktop-nav{display:flex;align-items:center;justify-content:flex-end;gap:1.5rem;flex:1 1 auto;min-width:0;flex-wrap:nowrap;white-space:nowrap}
.desktop-nav a,.desktop-nav .nav-unavailable{font-size:1rem;font-weight:700}
.nav-unavailable{color:var(--ink);font-size:1rem;font-weight:400}
.menu-button{display:none;min-height:3rem;padding:.75rem 1rem;border:0;border-radius:.5rem;background:var(--brown);color:#FFFFFF;font-size:1rem;font-weight:700;cursor:pointer}
.mobile-nav{display:none;width:min(60rem,calc(100% - 2rem));margin:1rem auto 0;padding:1rem;border:.0625rem solid var(--line);border-radius:1.5rem;background:#FFFFFF}
.mobile-nav.open{display:flex;flex-direction:column;gap:1rem}
.mobile-nav a,.mobile-nav .nav-unavailable{display:block;min-height:2.75rem;padding:.5rem 0}
main,.wp-site-blocks main{width:min(60rem,calc(100% - 2rem));margin:1.5rem auto 3rem}
.zone{margin:0 0 1.5rem;padding:2rem;border:.0625rem solid var(--line);border-radius:1.5rem;background:#FFFFFF}
.hero{background:var(--green);color:#FFFFFF;border:0}
.hero h1,.hero h2,.hero p,.hero a{color:#FFFFFF}
.hero h1{margin:.5rem 0 1rem;font-size:1.4rem;line-height:1.4;font-weight:700}
.hero p{margin:0 0 1rem}
.hero p:last-child{margin-bottom:0}
.breadcrumb,.byline,.short-answer{font-size:1rem;font-weight:400}
h2{margin:0 0 1rem;color:var(--green);font-size:1.2rem;line-height:1.4;font-weight:700}
h3{margin:.75rem 0 .5rem;color:var(--green);font-size:1rem;line-height:1.4;font-weight:700}
p{margin:0 0 1rem}
p:last-child{margin-bottom:0}
.disclosure{padding:1.25rem;border:.125rem solid var(--gold);border-radius:.75rem;background:var(--yellow);color:#000000;font-size:1.333rem;line-height:1.5;font-weight:400}
.education{background:#FFFFFF}
.bite-photo{display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;border-radius:1.5rem}
.bite-photo-wrap{float:left;width:40%;max-width:26ch;margin:0 1.25rem .75rem 0}
.photo-credit{margin:.25rem 0 1rem;text-align:center;color:#000000;font-size:.85rem;font-weight:400}
.education-second{clear:both;padding-top:.5rem}
.layer-zone,.pairing-zone{background:var(--mint)}
.layer-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
.layer-card{padding:1rem;border:.0625rem solid var(--line);border-radius:.75rem;background:#FFFFFF}
.layer-card h3{margin:0 0 .5rem;font-size:1.2rem}
.layer-card p{margin:0}
.layer-close{margin:1rem 0 0}
.comparison{background:#FFFFFF}
.table-wrap{max-width:100%;overflow-x:auto;border:.125rem solid #000000;border-radius:.5rem}
table{width:100%;min-width:42rem;border-collapse:collapse;color:var(--ink);font-size:1rem}
th,td{padding:.75rem;border:.0625rem solid #000000;text-align:left;vertical-align:top}
th{background:#FFFFFF;color:#000000;font-weight:700}
.barrier-zone{background:var(--beige)}
.product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,14rem));justify-content:center;gap:1rem}
.product-card{display:flex;flex-direction:column;width:100%;max-width:14rem;padding:1rem;border:.0625rem solid var(--line);border-radius:.75rem;background:#FFFFFF}
.product-window{display:flex;width:100%;aspect-ratio:16/10;align-items:center;justify-content:center;border:.125rem dashed var(--green);border-radius:1.5rem;background:#FFFFFF;color:#000000;text-align:center;text-decoration:none;font-size:1rem;font-weight:400}
.product-card h3{margin:.75rem 0 .5rem}
.caption-line{margin:0 0 .5rem;color:#000000;font-size:1rem;font-weight:400}
.caption-line strong{font-weight:700}
.card-spacer{flex:1 0 1rem;min-height:1rem}
.product-cta{display:flex;align-items:center;justify-content:center;min-height:3rem;margin-top:.5rem;padding:.75rem 1rem;border-radius:.5rem;background:var(--brown);color:#FFFFFF;text-align:center;text-decoration:none;font-size:1rem;font-weight:700}
.product-cta:hover{background:var(--brown);color:#FFFFFF}
.footer-zone{background:var(--green);color:#FFFFFF;border:0}
.footer-zone h2,.footer-zone h3,.footer-zone p,.footer-zone a,.footer-zone .nav-unavailable{color:#FFFFFF}
.footer-nav{display:flex;align-items:center;gap:1.5rem;flex-wrap:wrap;margin:1rem 0}
.footer-nav a,.footer-nav .nav-unavailable{font-size:1rem}
.copyright{margin:1rem 0 0}
@media(max-width:60rem){
 .desktop-nav{display:none}
 .menu-button{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}
}
@media(max-width:48rem){
 .zone{padding:1.25rem;margin-bottom:1rem}
 .hero{padding:1.5rem 1.25rem}
 .layer-grid{grid-template-columns:minmax(0,1fr)}
 .product-grid{grid-template-columns:minmax(0,1fr)}
 .product-card{max-width:14rem;margin-inline:auto}
 .bite-photo-wrap{float:none;width:100%;max-width:none;margin:0 0 .75rem}
 .bite-photo{width:100%}
 .education-second{clear:both}
 .footer-nav{flex-direction:column;align-items:flex-start;gap:1rem}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

